<script setup lang="ts">import { reactive } from 'vue';import { useWorkspaceStore } from '../stores/workspace';import MoneyValue from '../components/MoneyValue.vue';import EmptyState from '../components/EmptyState.vue';const workspace=useWorkspaceStore();const form=reactive({name:'',category:'影音',amount:'',billingCycle:'monthly' as const,nextBilling:new Date().toISOString().slice(0,10),status:'active' as const,notes:''});async function submit(){const group=workspace.currentGroup;if(!group)return;await workspace.addSubscription({name:form.name,category:form.category,amountMinor:Math.round(Number(form.amount)*100),currency:group.currency,billingCycle:form.billingCycle,nextBilling:new Date(form.nextBilling).toISOString(),status:form.status,notes:form.notes});form.name='';form.amount='';form.notes=''}</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">RECURRING</p><h1>訂閱管理</h1><p>以最小貨幣單位保存金額，避免浮點誤差。</p></div></div><div class="two-column content-heavy"><div class="card"><div class="card-title"><h2>所有訂閱</h2><span>{{ workspace.subscriptions.length }} 筆</span></div><div v-if="workspace.subscriptions.length" class="rows"><div v-for="item in workspace.subscriptions" :key="item.id" class="row"><div class="service-icon">{{ item.name.slice(0,1) }}</div><div class="grow"><strong>{{ item.name }}</strong><small>{{ item.category||'未分類' }} · 下次 {{ new Date(item.nextBilling).toLocaleDateString('zh-TW') }}</small></div><div class="money"><MoneyValue :amount="item.amountMinor" :currency="item.currency"/><small>/ {{ item.billingCycle==='monthly'?'月':item.billingCycle==='quarterly'?'季':'年' }}</small></div><button class="icon-button" aria-label="刪除" @click="workspace.deleteSubscription(item.id)">×</button></div></div><EmptyState v-else title="還沒有訂閱" description="加入第一筆固定扣款。" /></div><form class="card form-card sticky" @submit.prevent="submit"><h2>新增訂閱</h2><label>名稱<input v-model="form.name" required placeholder="例如 Netflix"></label><div class="form-row"><label>分類<input v-model="form.category"></label><label>金額<input v-model="form.amount" type="number" min="0" step="0.01" required></label></div><div class="form-row"><label>週期<select v-model="form.billingCycle"><option value="monthly">每月</option><option value="quarterly">每季</option><option value="yearly">每年</option></select></label><label>下次扣款<input v-model="form.nextBilling" type="date" required></label></div><label>備註<textarea v-model="form.notes" rows="2"></textarea></label><button class="primary">新增訂閱</button></form></div></section></template>
